t.script:
document.addEventListener('DOMContentLoaded', ()=> {
        const cards=document.querySelectorAll('#sPopup1754558420306 .newsletter_wizard_card');
        if ( !cards.length) return;

        cards.forEach((card)=> {
                const endMsg=card.querySelector('.s_website_form_end_message');
                if ( !endMsg) return;

                const syncThankYouState=()=> {
                    card.classList.toggle('is-thank-you', !endMsg.classList.contains('d-none'));
                }

                ;

                syncThankYouState();

                const endMsgObserver=new MutationObserver(syncThankYouState);

                endMsgObserver.observe(endMsg, {
                    attributes: true, attributeFilter: ['class']
                });
        });
});

const initOdooWizard=()=> {
        const DEBUG_WIZARD=true;
        const forms=document.querySelectorAll('form.o_form_wizard');
        if ( !forms.length) return;

        const getLabelText=(fieldEl)=> {
            const labelContent=fieldEl.querySelector('.s_website_form_label_content');
            if (labelContent && labelContent.textContent.trim()) return labelContent.textContent.trim();

            const label=fieldEl.querySelector('label');
            if (label && label.textContent.trim()) return label.textContent.replace(/\*/g, '').trim();

            return (fieldEl.getAttribute('data-translated-name') || fieldEl.getAttribute('data-name') || 'Pergunta').trim();
        }

        ;

        /**
   * Determine if the *field* is conditionally hidden by Odoo/Bootstrap,
   * WITHOUT being fooled by the wizard step wrapper (which is hidden by design).
   */
        const isFieldConditionallyVisible=(fieldEl)=> {
            if ( !fieldEl) return false;

            // If Odoo/Bootstrap marks it hidden
            const hiddenClassList=[ 'd-none',
            'o_invisible_modifier',
            'o_snippet_invisible',
            'o_hidden',
            'visually-hidden',
            's_website_form_field_hidden'
            ];

            let cur=fieldEl;

            while (cur && cur !==document.documentElement) {
                // Stop climbing once we reach the wizard step; above that is hidden by our UI
                if (cur.classList && cur.classList.contains('o_form_wizard_q')) break;

                if (cur.hidden) return false;

                if (cur.getAttribute && cur.getAttribute('aria-hidden')==='true') return false;

                if (cur.classList) {
                    for (const c of hiddenClassList) {
                        if (cur.classList.contains(c)) return false;
                    }
                }

                // Inline style display none is a strong signal
                if (cur.style && cur.style.display==='none') return false;

                cur=cur.parentElement;
            }

            return true;
        }

        ;

        const isStepConditionallyVisible=(stepEl)=> {
            if ( !stepEl) return false;
            const fieldEl=stepEl.querySelector('.s_website_form_field');
            return isFieldConditionallyVisible(fieldEl);
        }

        ;

        const syncConditionalRequired=(steps)=> {
            steps.forEach((stepEl)=> {
                    const fieldEl=stepEl.querySelector('.s_website_form_field');
                    if ( !fieldEl) return;

                    const isVisible=isStepConditionallyVisible(stepEl);
                    const inputs=fieldEl.querySelectorAll('input, select, textarea');

                    inputs.forEach((input)=> {
                            if (input.type==='hidden') return;

                            if ( !isVisible) {
                                if (input.required) input.dataset.wizardRequired='1';
                                if (input.dataset.wizardRequired==='1') input.required=false;
                                return;
                            }

                            if (input.dataset.wizardRequired==='1') input.required=true;
                        });
                });
        }

        ;

        const isStepAnswered=(stepEl)=> {
            // Hidden by condition? Skip it
            if ( !isStepConditionallyVisible(stepEl)) return true;

            const fields=Array.from(stepEl.querySelectorAll('input, select, textarea'))
                .filter((f)=> f.type !=='hidden' && !f.disabled);
            if ( !fields.length) return true;

            const checkboxes=fields.filter((f)=> f.type==='checkbox');
            if (checkboxes.length) return checkboxes.some(c=> c.checked);

            const field=fields[0];
            const value=(field.value || '').trim();

            // Text fields: only require non-empty (avoids false negatives from browser validity)
            if (field.type==='text') return value.length > 0;

            if (typeof field.checkValidity==='function') return field.checkValidity();
            return value.length > 0;
        }

        ;

        const focusFirstField=(stepEl)=> {
            const field=stepEl.querySelector('input:not([type="hidden"]), textarea, select');

            if (field) field.focus({
                preventScroll: true
            });
    }

    ;

    const showStepWithFade=(steps, nextIndex, currentIndex)=> {
        const currentStep=steps[currentIndex];
        const nextStep=steps[nextIndex];

        if (currentStep) currentStep.classList.remove('is-visible');

        window.setTimeout(()=> {
                steps.forEach((s, i)=> s.classList.toggle('is-active', i===nextIndex));
                void nextStep.offsetWidth; // reflow
                nextStep.classList.add('is-visible');
                focusFirstField(nextStep);
            }

            , 180);
    }

    ;

    const safeSubmit=(form)=> {
        if (DEBUG_WIZARD) console.log('[wizard] submit start', {
            id: form.id, model: form.dataset.model_name
        });
    // Prefer Odoo's handler (usually bound to this button)
    const odooSend=form.querySelector('a.s_website_form_send, button.s_website_form_send, input.s_website_form_send');

    if (odooSend) {
        const wasDisabled=odooSend.hasAttribute('disabled') || odooSend.classList.contains('disabled') || odooSend.classList.contains('o_btn_loading') || odooSend.classList.contains('pe-none') || odooSend.getAttribute('aria-disabled')==='true';

        if (DEBUG_WIZARD) {
            console.log('[wizard] click odooSend', {
                disabled: wasDisabled,
                classes: odooSend.className
            });
    }

    if (wasDisabled) {
        odooSend.classList.remove('disabled', 'o_btn_loading', 'pe-none');
        odooSend.removeAttribute('disabled');
        odooSend.setAttribute('aria-disabled', 'false');
    }

    odooSend.click();
    return;
}

// Next: submit via a real submitter to trigger the form's submit event.
const hiddenSubmit=form.querySelector('.o_form_wizard_hidden_submit');

if (hiddenSubmit && typeof form.requestSubmit==='function') {
    if (DEBUG_WIZARD) console.log('[wizard] requestSubmit(hiddenSubmit)');
    form.requestSubmit(hiddenSubmit);
    return;
}

// Next fallback: triggers submit event (Odoo hooks into it)
if (typeof form.requestSubmit==='function') {
    if (DEBUG_WIZARD) console.log('[wizard] requestSubmit()');
    form.requestSubmit();
    return;
}

// Last resort: click a real submit control if any exists
const realSubmit=form.querySelector('button[type="submit"], input[type="submit"]');

if (realSubmit) {
    if (DEBUG_WIZARD) console.log('[wizard] click realSubmit', realSubmit);
    realSubmit.click();
    return;
}

// Final fallback: may bypass listeners
if (DEBUG_WIZARD) console.log('[wizard] form.submit()');
form.submit();
}

;

forms.forEach((form)=> {

        // Studio-safe: if Studio saved an init flag, still recover by checking actual nav binding
        // Use a runtime init marker, but don't hard-return unless we are sure it's already bound.
        if (form.dataset.wizardJsInit==='1' && form.querySelector('.o_form_wizard_nav')) {
            // Ensure nav has listeners? We can't introspect listeners reliably, so we'll still rebuild bindings safely below.
            // Do not return.
        }

        const rows=form.querySelector('.s_website_form_rows');
        if ( !rows) return;

        if (DEBUG_WIZARD) {
            console.log('[wizard] init form', {
                id: form.id || null,
                model: form.dataset.model_name || null,
                ready: form.dataset.wizardReady || null,
                navFound: !!form.querySelector('.o_form_wizard_nav')
            });
        }

        if (DEBUG_WIZARD) {
            form.addEventListener('submit', (e)=> {
                    const invalid=Array.from(form.querySelectorAll(':invalid'));

                    console.log('[wizard] submit event', {
                        defaultPrevented: e.defaultPrevented,
                        valid: form.checkValidity(),
                        invalidCount: invalid.length
                    });
                if (invalid.length) console.log('[wizard] invalid fields', invalid);
            });
    }

    // Ensure a hidden submit exists for reliable programmatic submit.
    let hiddenSubmit=form.querySelector('.o_form_wizard_hidden_submit');

    if ( !hiddenSubmit) {
        hiddenSubmit=document.createElement('button');
        hiddenSubmit.type='submit';
        hiddenSubmit.className='o_form_wizard_hidden_submit';
        hiddenSubmit.style.display='none';
        form.appendChild(hiddenSubmit);
    }

    // Detect if steps already exist (Studio may have saved the mutated DOM)
    let steps=Array.from(rows.querySelectorAll(':scope > .o_form_wizard_q'));

    // If steps do not exist, build them from raw fields
    if ( !steps.length) {
        const fieldEls=Array.from(rows.children).filter(el=>
            el.classList.contains('s_website_form_field') &&
            !el.classList.contains('s_website_form_field_hidden'));

        if (fieldEls.length <=1) return;

        // Wrap into centered card (only if not already wrapped)
        let wrap=rows.closest('.o_form_wizard_wrap');
        let card=rows.closest('.o_form_wizard_card');

        if ( !wrap || !card) {
            wrap=document.createElement('div');
            wrap.className='o_form_wizard_wrap';

            card=document.createElement('div');
            card.className='o_form_wizard_card';

            wrap.appendChild(card);
            rows.parentNode.insertBefore(wrap, rows);
            card.appendChild(rows);
        }

        steps=fieldEls.map((fieldEl, idx)=> {
                const step=document.createElement('div');
                step.className='o_form_wizard_q';
                step.dataset.stepIndex=String(idx);

                const title=document.createElement('div');
                title.className='o_form_wizard_title';
                title.textContent=getLabelText(fieldEl);

                step.appendChild(title);
                step.appendChild(fieldEl);

                rows.insertBefore(step, rows.firstChild);
                return step;
            });

        // Reorder steps if needed (because we inserted at firstChild repeatedly)
        steps=steps .slice() .sort((a, b)=> parseInt(a.dataset.stepIndex || '0', 10) - parseInt(b.dataset.stepIndex || '0', 10));
    }

    else {
        // Ensure we have a card wrapper; if missing, we create it around rows
        let card=rows.closest('.o_form_wizard_card');

        if ( !card) {
            const wrap=document.createElement('div');
            wrap.className='o_form_wizard_wrap';

            card=document.createElement('div');
            card.className='o_form_wizard_card';

            wrap.appendChild(card);
            rows.parentNode.insertBefore(wrap, rows);
            card.appendChild(rows);
        }
    }

    // submit row (may be inside rows or later)
    const submitRow=rows.querySelector('.s_website_form_submit') || form.querySelector('.s_website_form_submit');
    const card=rows.closest('.o_form_wizard_card') || rows.parentElement;

    // If Studio saved the wizard steps out of order (common when DOM was mutated),
    // sort them by data-step-index and reattach in the correct order.
    if (steps.length > 1) {
        const sorted=steps.slice().sort((a, b)=>
            parseInt(a.dataset.stepIndex || '0', 10) - parseInt(b.dataset.stepIndex || '0', 10));
        const anchor=(submitRow && submitRow.parentElement===rows) ? submitRow : null;
        sorted.forEach((s)=> rows.insertBefore(s, anchor));
        steps=sorted;
    }


    // Ensure nav exists
    let nav=card.querySelector(':scope > .o_form_wizard_nav');

    if ( !nav) {
        nav=document.createElement('div');
        nav.className='o_form_wizard_nav';
        nav.innerHTML=` ↑ ↓ `;
        card.appendChild(nav);
    }

    else {

        // If Studio saved nav with old labels, keep it but ensure buttons exist
        if ( !nav.querySelector('.js_prev') || !nav.querySelector('.js_next')) {
            nav.innerHTML=` ↑ ↓ `;
        }
    }

    // Remove any previous click handlers by replacing buttons (safe rebinding)
    const prevOld=nav.querySelector('.js_prev');
    const nextOld=nav.querySelector('.js_next');
    const prevBtn=prevOld.cloneNode(true);
    const nextBtn=nextOld.cloneNode(true);
    prevOld.parentNode.replaceChild(prevBtn, prevOld);
    nextOld.parentNode.replaceChild(nextBtn, nextOld);

    let current=0;

    const getNextVisibleIndex=(from, dir)=> {
        let i=from;

        while (true) {
            i +=dir;
            if (i < 0 || i >=steps.length) return null;
            if (isStepConditionallyVisible(steps[i])) return i;
        }
    }

    ;

    const getFirstVisibleIndex=()=> {
        for (let i=0; i < steps.length; i++) {
            if (isStepConditionallyVisible(steps[i])) return i;
        }

        return 0;
    }

    ;

    const ensureCurrentIsVisible=()=> {
        if (isStepConditionallyVisible(steps[current])) return;

        const next=getNextVisibleIndex(current, +1);

        if (next !==null) {
            current=next; return;
        }

        const prev=getNextVisibleIndex(current, -1);

        if (prev !==null) {
            current=prev; return;
        }

        current=getFirstVisibleIndex();
    }

    ;

    const renderNav=()=> {
        ensureCurrentIsVisible();
        syncConditionalRequired(steps);

        prevBtn.classList.toggle('is-disabled', getNextVisibleIndex(current, -1)===null);

        const isLastVisible=(getNextVisibleIndex(current, +1)===null);

        // show/hide default Odoo submit row only on last step
        if (submitRow) submitRow.style.display=isLastVisible ? '' : 'none';

        nextBtn.textContent=isLastVisible ? 'Submeter' : '↓';
        nextBtn.classList.toggle('o_form_wizard_ok', isLastVisible);
    }

    ;

    const renderStep=(initial=false)=> {
        ensureCurrentIsVisible();
        steps.forEach((s, i)=> s.classList.toggle('is-active', i===current));

        if (initial) {
            window.setTimeout(()=> steps[current].classList.add('is-visible'), 0);
        }

        else {
            steps[current].classList.add('is-visible');
        }

        focusFirstField(steps[current]);
        renderNav();
    }

    ;

    const goNext=()=> {
        if (DEBUG_WIZARD) console.log('[wizard] next click', {
            current, total: steps.length
        });
    ensureCurrentIsVisible();
    syncConditionalRequired(steps);

    const stepEl=steps[current];

    if ( !isStepAnswered(stepEl)) {
        if (DEBUG_WIZARD) console.log('[wizard] step invalid', stepEl);
        const firstField=stepEl.querySelector('input, textarea, select');
        if (firstField && typeof firstField.reportValidity==='function') firstField.reportValidity();
        return;
    }

    const next=getNextVisibleIndex(current, +1);

    if (next !==null) {
        const old=current;
        current=next;
        showStepWithFade(steps, current, old);
        renderNav();
        return;
    }

    // Last visible step -> submit reliably
    safeSubmit(form);
}

;

const goPrev=()=> {
    if (DEBUG_WIZARD) console.log('[wizard] prev click', {
        current, total: steps.length
    });
    ensureCurrentIsVisible();
    const prev=getNextVisibleIndex(current, -1);
    if (prev===null) return;

    const old=current;
    current=prev;
    showStepWithFade(steps, current, old);
    renderNav();
}

;

const logNavHitTest=(btn, name)=> {
    if ( !DEBUG_WIZARD || !btn) return;
    const rect=btn.getBoundingClientRect();
    const cx=rect.left + rect.width / 2;
    const cy=rect.top + rect.height / 2;
    const topEl=document.elementFromPoint(cx, cy);
    console.log('[wizard] nav hittest', {
        name,
        center: {
            x: Math.round(cx),
            y: Math.round(cy)
        },
        button: btn,
        topElement: topEl,
        blocked: !!topEl && topEl !==btn && !btn.contains(topEl)
    });
}

;

logNavHitTest(prevBtn, 'prev');
logNavHitTest(nextBtn, 'next');

nextBtn.addEventListener('pointerdown', ()=> logNavHitTest(nextBtn, 'next-pointerdown'));
prevBtn.addEventListener('pointerdown', ()=> logNavHitTest(prevBtn, 'prev-pointerdown'));
nextBtn.addEventListener('click', goNext);
prevBtn.addEventListener('click', goPrev);

if (DEBUG_WIZARD) console.log('[wizard] listeners bound', {
    prevBtn,
    nextBtn,
    card,
    nav
});

form.addEventListener('keydown', (e)=> {
        if (e.key !=='Enter') return;
        const activeStep=steps[current];
        if (activeStep && activeStep.querySelector('textarea:focus')) return;
        e.preventDefault();
        goNext();
    });

// Observe changes that might toggle visibility classes
const mo=new MutationObserver(()=> {
        const was=current;
        ensureCurrentIsVisible();
        if (current !==was) showStepWithFade(steps, current, was);
        renderNav();
    });

mo.observe(form, {
    attributes: true,
    subtree: true,
    attributeFilter: ['class', 'style', 'hidden', 'aria-hidden']
});

const resetWizard=()=> {
    current=getFirstVisibleIndex();
    renderStep(true);
}

;

form.addEventListener('o-wizard-reset', resetWizard);

// Init
current=getFirstVisibleIndex();
renderStep(true);

    // Mark runtime init
    form.dataset.wizardJsInit='1';
});

if (document.readyState==='loading') {
    document.addEventListener('DOMContentLoaded', initOdooWizard);
}
else {
    initOdooWizard();
}


if (typeof window !=='undefined') {
    console.log('[wizard] script loaded homepage');
}

const bindWizardFallback=()=> {
    const forms=document.querySelectorAll('form.o_form_wizard');
    if ( !forms.length) {
        console.log('[wizard:fallback] no forms found');
        return;
    }

    forms.forEach((form)=> {
            if (form.dataset.wizardFallbackInit==='1') return;
            form.dataset.wizardFallbackInit='1';

            const isStepVisible=(step)=> {
                if ( !step) return false;
                if (step.classList.contains('d-none') || step.classList.contains('o_invisible_modifier')) return false;
                return window.getComputedStyle(step).display !=='none';
            }

            ;

            const getSteps=()=> Array.from(form.querySelectorAll('.o_form_wizard_q'));

            const getCurrentIndex=(steps)=> {
                const idx=steps.findIndex((s)=> s.classList.contains('is-active'));
                return idx >=0 ? idx :0;
            }

            ;

            const render=(steps, idx)=> {
                steps.forEach((step, i)=> {
                        step.classList.toggle('is-active', i===idx);
                        step.classList.toggle('is-visible', i===idx);
                    });
            }

            ;

            form.addEventListener('click', (ev)=> {
                    const nextBtn=ev.target.closest('.o_form_wizard_btn.js_next');
                    const prevBtn=ev.target.closest('.o_form_wizard_btn.js_prev');
                    if ( !nextBtn && !prevBtn) return;

                    const steps=getSteps();
                    if ( !steps.length) {
                        console.log('[wizard:fallback] no steps');
                        return;
                    }

                    let current=getCurrentIndex(steps);
                    console.log('[wizard:fallback] nav click', {
                        type: nextBtn ? 'next' : 'prev',
                        current,
                        steps: steps.length
                    });

                    if (nextBtn) {
                        for (let i=current + 1; i < steps.length; i++) {
                            if (isStepVisible(steps[i])) {
                                render(steps, i);
                                return;
                            }
                        }
                        const submitBtn=form.querySelector('.s_website_form_send');
                        if (submitBtn) submitBtn.click();
                        return;
                    }

                    for (let i=current - 1; i >=0; i--) {
                        if (isStepVisible(steps[i])) {
                            render(steps, i);
                            return;
                        }
                    }
                }, true);

            console.log('[wizard:fallback] bound', {
                id: form.id || null,
                model: form.dataset.model_name || null
            });
        });
}

;

if (document.readyState==='loading') {
    document.addEventListener('DOMContentLoaded', bindWizardFallback);
}
else {
    bindWizardFallback();
}
window.setTimeout(bindWizardFallback, 1200);
window.addEventListener('load', bindWizardFallback);

const applyMobileFloatingBlocks=()=> {
    const isMobile=window.matchMedia('(max-width: 991.98px)').matches;
    const blocks=document.querySelectorAll('#wrap .s_floating_blocks .s_floating_blocks_block');

    blocks.forEach((block)=> {
            if (isMobile) {
                if (block.dataset.origMinHeight===undefined) block.dataset.origMinHeight=block.style.minHeight || '';
                if (block.dataset.origPaddingTop===undefined) block.dataset.origPaddingTop=block.style.paddingTop || '';
                if (block.dataset.origPaddingBottom===undefined) block.dataset.origPaddingBottom=block.style.paddingBottom || '';
                block.style.minHeight='150px';
                block.style.paddingTop='16px';
                block.style.paddingBottom='16px';
                return;
            }

            if (block.dataset.origMinHeight !==undefined) block.style.minHeight=block.dataset.origMinHeight;
            if (block.dataset.origPaddingTop !==undefined) block.style.paddingTop=block.dataset.origPaddingTop;
            if (block.dataset.origPaddingBottom !==undefined) block.style.paddingBottom=block.dataset.origPaddingBottom;
        });

    const grids=document.querySelectorAll('#wrap .s_floating_blocks .s_floating_blocks_block_grid');

    grids.forEach((grid)=> {
            if (isMobile) {
                if (grid.dataset.origMinHeight===undefined) grid.dataset.origMinHeight=grid.style.minHeight || '';
                grid.style.minHeight='80px';
                return;
            }

            if (grid.dataset.origMinHeight !==undefined) grid.style.minHeight=grid.dataset.origMinHeight;
        });
}

;

applyMobileFloatingBlocks();
window.addEventListener('resize', applyMobileFloatingBlocks);

// Lightweight global fade-in for homepage sections
const animatedSections=Array.from(document.querySelectorAll('#wrap section[data-snippet]')) .filter((el)=> !el.closest('.modal') && !el.closest('.s_popup'));

if (animatedSections.length) {
    animatedSections.forEach((el)=> el.classList.add('fade-in-on-scroll'));

    const io=new IntersectionObserver((entries)=> {
            entries.forEach((entry)=> {
                    if (entry.isIntersecting) {
                        entry.target.classList.add('is-visible');
                        io.unobserve(entry.target);
                    }
                });
        }

        , {
        threshold: 0.2
    });

animatedSections.forEach((el)=> io.observe(el));
}
};

div.script:
document.addEventListener('DOMContentLoaded', function () {
        const toggleButtons=Array.from(document.querySelectorAll('#catalog-download-toggle, #catalog-download-toggle-mobile'));
        const formSection=document.getElementById('catalog-download-section');

        if ( !toggleButtons.length || !formSection) {
            return;
        }

        formSection.classList.add('d-none');

        const toggleVisibility=(event)=> {
            event.preventDefault();
            formSection.classList.toggle('d-none');

            if ( !formSection.classList.contains('d-none')) {
                const form=formSection.querySelector('form.o_form_wizard');

                if (form) {
                    form.dispatchEvent(new Event('o-wizard-reset'));
                }

                formSection.scrollIntoView({
                    behavior: 'smooth', block: 'start'
                });
        }
    }

    ;

    toggleButtons.forEach((toggleBtn)=> {
            toggleBtn.addEventListener('click', toggleVisibility);
        });
});

document.addEventListener('DOMContentLoaded', function () {
        const popupWrapper=document.querySelector('.s_popup.o_newsletter_popup');

        if ( !popupWrapper) {
            return;
        }

        const modalEl=popupWrapper.querySelector('.modal');

        if ( !modalEl) {
            return;
        }

        const rawDelay=parseInt(modalEl.dataset.showAfter || '0', 10);
        const delay=Number.isNaN(rawDelay) ? 0 : rawDelay;

        const closeModal=()=> {
            modalEl.classList.remove('show');
            modalEl.style.display='none';
            modalEl.setAttribute('aria-hidden', 'true');
            modalEl.removeAttribute('aria-modal');
            document.body.classList.remove('modal-open');
            const backdrop=document.querySelector('.modal-backdrop');

            if (backdrop) {
                backdrop.remove();
            }
        }

        ;

        const ensureBackdrop=()=> {
            let backdrop=document.querySelector('.modal-backdrop');

            if ( !backdrop) {
                backdrop=document.createElement('div');
                backdrop.className='modal-backdrop fade show';
                document.body.appendChild(backdrop);
            }

            return backdrop;
        }

        ;

        const showModal=()=> {
            popupWrapper.classList.remove('o_snippet_invisible', 'd-none');
            modalEl.style.display='block';
            modalEl.classList.add('show');
            modalEl.setAttribute('aria-hidden', 'false');
            modalEl.setAttribute('aria-modal', 'true');
            document.body.classList.add('modal-open');
            const backdrop=ensureBackdrop();

            backdrop.addEventListener('click', closeModal, {
                once: true
            });
    }

    ;

    const closeBtn=popupWrapper.querySelector('.s_popup_close');

    if (closeBtn) {
        closeBtn.addEventListener('click', closeModal);
    }

    window.setTimeout(showModal, delay);
});
